function validate([board]) {
  if (!Array.isArray(board) || board.length < 3 || board.length > 100) return 'board needs 3 to 100 rows.';
  const n = board[0].length;
  if (n < 3 || n > 100) return 'Each row needs 3 to 100 cells.';
  if (board.some(row => row.length !== n)) return 'Every row must have the same length.';
  if (board.some(row => row.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000))) return 'Each value is a whole number from -10^9 to 10^9.';
  return null;
}

