function maximumValueSum(board) {
  const m = board.length;
  const keepThree = cells => {
    cells.sort((a, b) => b[0] - a[0]);
    const kept = [];
    for (const cell of cells) {
      if (kept.length < 3 && kept.every(other => other[1] !== cell[1])) kept.push(cell);
    }
    return kept;
  };

  const top = board.map(row => keepThree(row.map((value, col) => [value, col])));
  const above = [top[0]];
  for (let r = 1; r < m; r++) {
    above[r] = keepThree([...above[r - 1], ...top[r]]);
  }
  const below = [];
  below[m - 1] = top[m - 1];
  for (let r = m - 2; r >= 0; r--) {
    below[r] = keepThree([...below[r + 1], ...top[r]]);
  }

  let best = -Infinity;
  for (let mid = 1; mid < m - 1; mid++) {
    for (const [v1, c1] of above[mid - 1]) {
      for (const [v2, c2] of top[mid]) {
        if (c2 === c1) continue;
        for (const [v3, c3] of below[mid + 1]) {
          if (c3 === c1 || c3 === c2) continue;
          best = Math.max(best, v1 + v2 + v3);
        }
      }
    }
  }
  return best;
}

