function maximumValueSum(board) {
  const m = board.length, n = board[0].length;
  const used = new Array(n).fill(false);
  // Go down the rows: each row either stays empty or gets one rook in a column no earlier rook uses.
  const place = (row, left) => {
    if (left === 0) return 0;
    if (m - row < left) return -Infinity;
    let best = place(row + 1, left);
    for (let col = 0; col < n; col++) {
      if (used[col]) continue;
      used[col] = true;
      best = Math.max(best, board[row][col] + place(row + 1, left - 1));
      used[col] = false;
    }
    return best;
  };
  return place(0, 3);
}

