function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const m = size === 'large' ? 100 : 3 + pick(4);
  const n = size === 'large' ? [100, 100, 3][pick(3)] : 3 + pick(4);
  // Tiny spans give many ties, huge ones reach the limits; some boards hold only negative values.
  const span = size === 'large' ? 1000000000 : [2, 9, 1000000000][pick(3)];
  const negative = rand() < 0.25;
  const value = () => negative ? -1 - pick(span) : pick(2 * span + 1) - span;
  const board = Array.from({ length: m }, () => Array.from({ length: n }, value));
  // Sometimes one column holds the largest value of every row, so the rows' favourite cells clash.
  if (rand() < 0.4) {
    const col = pick(n);
    for (const row of board) row[col] = Math.min(span, Math.max(...row) + 1 + pick(3));
  }
  return [board];
}
